from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Use Counter to get frequency counts for each character
    char_counts = Counter(test)

    # Find the maximum frequency count
    max_count = max(char_counts.values())

    # Create a list of characters that have the maximum frequency count
    most_common_chars = [char for char, freq in char_counts.items() if freq == max_count]

    return dict(zip(most_common_chars, char_counts.most_common()))

