from collections import deque

def bf(planet1, planet2):
    # Check if both planet names are valid
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    # Initialize a deque with the planets' orbits
    dq = deque(sorted(["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]))

    # Add planet1's orbit to the deque
    dq.appendleft(planet1)

    # Iterate through the remaining planets
    for i in range(len(dq) - 1):
        # If the current planet's orbit is before the next planet's orbit, remove it from the deque
        if dq[i] < dq[i + 1]:
            dq.popleft()

    # Return the resulting deque
    return tuple(dq)


